const EXAMPLE = `{
  "id": "LB_S1_21",
  "title": "Lesson title",
  "source": "FinnishPod101 · Lower Beginner S1 #21",
  "glossary": [
    { "w": "sana", "ru": "word", "en": "word",
      "forms": ["sana", "sanaa"], "note": "Explanation from the lesson" }
  ],
  "items": [
    { "fi": "Tämä on lause.", "ru": "This is a sentence.",
      "en": "This is a sentence.", "k": "s" }
  ]
}`;

function Import({ lessons, onSave, progress, onProgress, makeBackup, onBackedUp, onBack }) {
  const [text, setText] = useState("");
  const [msg, setMsg] = useState(null);
  const [showFmt, setShowFmt] = useState(false);
  const [fi, setFi] = useState("");
  const [ru, setRu] = useState("");
  const [en, setEn] = useState("");
  const [phraseMsg, setPhraseMsg] = useState(null);
  const [addingPhrase, setAddingPhrase] = useState(false);

  const addPhrase = async () => {
    if (!fi.trim() || !ru.trim()) return;
    setAddingPhrase(true);
    const item = { fi: fi.trim(), ru: ru.trim(), en: en.trim(), k: "s" };
    const existing = lessons.find((l) => l.id === CUSTOM_LESSON_ID);
    const next = existing
      ? lessons.map((l) => (l.id === CUSTOM_LESSON_ID ? { ...l, items: [...l.items, item] } : l))
      : [...lessons, { id: CUSTOM_LESSON_ID, title: "My Phrases", source: "Added manually", glossary: [], items: [item] }];
    const ok = await onSave(next);
    setAddingPhrase(false);
    setPhraseMsg(
      ok
        ? { bad: false, t: "Phrase added — it's in the “My Phrases” level, which is always unlocked." }
        : { bad: true, t: "Phrase added, but it couldn't be saved to storage — it will disappear after a reload." }
    );
    setFi(""); setRu(""); setEn("");
  };

  const fieldStyle = {
    width: "100%", padding: "11px 12px", fontSize: 15.5, borderRadius: 6,
    border: `1.5px solid ${C.line}`, background: C.card, color: C.ink, fontFamily: FONT, marginTop: 5,
  };

  const add = async () => {
    let data;
    try { data = JSON.parse(text); } catch (e) { setMsg({ bad: true, t: "This doesn't look like JSON. Check that you copied the whole text." }); return; }
    if (data && data.progress && typeof data.progress === "object") {
      const r = onProgress(data);
      setMsg({ bad: false, t: `Progress restored: phrases in progress ${r.phrases}, days of practice ${r.days}.`, done: true });
      setText("");
      return;
    }
    const arr = Array.isArray(data) ? data : [data];
    const good = [];
    for (const l of arr) {
      if (!l || !l.id || !Array.isArray(l.items) || !l.items.length) { setMsg({ bad: true, t: "The lesson is missing id or items fields." }); return; }
      if (l.items.some((it) => !it.fi || !it.ru)) { setMsg({ bad: true, t: "Every phrase needs fi and ru fields." }); return; }
      good.push({ glossary: [], ...l });
    }
    const known = new Set(lessons.map((l) => l.id));
    const fresh = good.filter((l) => !known.has(l.id));
    if (!fresh.length) {
      setMsg({ bad: true, t: "This lesson is already in the bank — it's either built into the app or was added earlier." });
      return;
    }
    const next = [...lessons, ...fresh];
    const ok = await onSave(next);
    const total = next.reduce((n, l) => n + l.items.length, 0);
    setMsg(
      ok
        ? { bad: false, t: `Lesson saved. Lessons: ${next.length}, phrases: ${total}.`, done: true }
        : { bad: true, t: `The lesson was added, but it couldn't be saved to storage — it will disappear after a reload. Send me this JSON in the chat and I'll build it into the app.`, done: true }
    );
    setText("");
  };

  const exportAll = async () => {
    try { await navigator.clipboard.writeText(JSON.stringify({ lessons }, null, 1)); setMsg({ bad: false, t: "The whole bank was copied to the clipboard." }); }
    catch (e) { setMsg({ bad: true, t: "The browser didn't allow access to the clipboard." }); }
  };

  return (
    <div style={{ maxWidth: 620, margin: "0 auto", padding: "calc(18px + env(safe-area-inset-top)) 18px 40px" }}>
      <TopBar title="Add Lesson" onBack={onBack} />

      <div style={{ marginTop: 16, fontSize: 15, fontWeight: 800, letterSpacing: "-0.01em" }}>Add your own phrase</div>
      <div style={{ fontSize: 13, color: C.inkSoft, marginTop: 2, lineHeight: 1.5 }}>
        It will appear in the “My Phrases” level — it's always unlocked, no need to wait your turn.
      </div>
      <input placeholder="In Finnish" value={fi} onChange={(e) => setFi(e.target.value)} style={fieldStyle} />
      <input placeholder="In English" value={ru} onChange={(e) => setRu(e.target.value)} style={fieldStyle} />
      <input placeholder="In English (optional)" value={en} onChange={(e) => setEn(e.target.value)} style={fieldStyle} />
      <div style={{ marginTop: 10 }}>
        <Primary onClick={addPhrase} disabled={!fi.trim() || !ru.trim() || addingPhrase}>
          {addingPhrase ? "Saving…" : "Add Phrase"}
        </Primary>
      </div>
      {phraseMsg && (
        <div style={{ marginTop: 10, background: phraseMsg.bad ? C.lingonSoft : C.spruceSoft, color: phraseMsg.bad ? C.lingon : C.spruce, padding: 12, borderRadius: 6, fontSize: 14, fontWeight: 600 }}>
          {phraseMsg.t}
        </div>
      )}

      <div style={{ marginTop: 24, height: 1, background: C.line }} />

      <div style={{ fontSize: 15, fontWeight: 800, marginTop: 20, letterSpacing: "-0.01em" }}>Add a lesson from a file</div>
      <div style={{ fontSize: 15, color: C.inkSoft, marginTop: 10, lineHeight: 1.5 }}>
        Send me the next lesson's PDF in the chat — I'll send back ready JSON with English translations and word notes. Paste it here. Saved progress is pasted here too.
      </div>

      <textarea value={text} onChange={(e) => setText(e.target.value)} rows={9} placeholder="Paste the lesson JSON or saved progress"
        style={{ width: "100%", marginTop: 14, padding: 13, fontSize: 14, borderRadius: 6, border: `1.5px solid ${C.line}`, background: C.card, color: C.ink, fontFamily: "ui-monospace, Menlo, monospace", resize: "vertical" }} />

      <div style={{ marginTop: 10 }}><Primary onClick={add} disabled={!text.trim()}>Add to the bank</Primary></div>

      {msg && (
        <div style={{ marginTop: 12, background: msg.bad ? C.lingonSoft : C.spruceSoft, color: msg.bad ? C.lingon : C.spruce, padding: 12, borderRadius: 6, fontSize: 14, fontWeight: 600 }}>
          {msg.t}
        </div>
      )}
      {msg && msg.done && (
        <div style={{ marginTop: 10 }}><Primary onClick={onBack}>To the lessons</Primary></div>
      )}

      <div style={{ marginTop: 20, display: "flex", flexDirection: "column", gap: 10 }}>
        <Ghost onClick={exportAll}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><Share2 size={16} /> Copy the whole bank as JSON</span>
        </Ghost>
        <Ghost onClick={async () => {
          try {
            await navigator.clipboard.writeText(JSON.stringify(makeBackup()));
            onBackedUp();
            setMsg({ bad: false, t: `Progress copied: ${Object.keys(progress || {}).length}phrases in progress. Save this text somewhere — pasting it back here will restore your counters.` });
          } catch (e) {
            setMsg({ bad: true, t: "The browser didn't allow access to the clipboard." });
          }
        }}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><Copy size={16} /> Copy progress</span>
        </Ghost>
        <Ghost onClick={() => setShowFmt(!showFmt)}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><Info size={16} /> {showFmt ? "Hide format" : "Show format"}</span>
        </Ghost>
      </div>

      {showFmt && (
        <pre style={{ marginTop: 12, background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, padding: 13, fontSize: 12.5, overflowX: "auto", color: C.ink, lineHeight: 1.5 }}>
{EXAMPLE}
        </pre>
      )}
      {showFmt && (
        <div style={{ marginTop: 10, fontSize: 13.5, color: C.inkSoft, lineHeight: 1.55 }}>
          k is the type: w word, s sentence, d dialogue line. forms are the word's forms that get underlined in exercises. note is the explanation that opens on tap.
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* ------------------------------------------------------------------ */
function Summary({ stats, mode, onHome, onAgain }) {
  const total = stats.ok + stats.no;
  const pct = total ? Math.round((stats.ok / total) * 100) : 0;
  return (
    <div style={{ maxWidth: 620, margin: "0 auto", padding: "calc(60px + env(safe-area-inset-top)) 18px 40px", textAlign: "center" }}>
      <div style={{ fontSize: 15, color: C.inkSoft, fontWeight: 600 }}>
        {mode === "verbs" ? "Verbs: training finished" : mode === "dialog" ? "Dialogue finished" : "Training finished"}
      </div>
      <div style={{ fontSize: 76, fontWeight: 800, letterSpacing: "-0.05em", color: pct >= 70 ? C.spruce : C.ochre, lineHeight: 1.05, marginTop: 6 }}>
        {pct}%
      </div>
      <div style={{ fontSize: 17, color: C.ink, marginTop: 4 }}>
        {stats.ok} / {total} correct
      </div>
      <div style={{ fontSize: 15, fontWeight: 700, color: C.blue, marginTop: 6 }}>
      </div>
      <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 7 }}>
        <Primary onClick={onAgain} tone="spruce">{mode === "verbs" ? "More verbs" : mode === "dialog" ? "Play again" : "One more round"}</Primary>
        <Ghost onClick={onHome}>Home</Ghost>
      </div>
    </div>
  );
}
